// 内嵌的7za.exe（base64编码）
// 这是终极解决方案：无论portable模式如何，7za.exe都一定能找到
// 文件大小: 602112 字节
const SEVEN_ZA_BASE64 = "";

/**
 * 把内嵌的7za.exe写入到临时目录
 * @returns 7za.exe的临时路径
 */
export function extractEmbedded7za(): string {
  const tempDir = require("os").tmpdir();
  const targetDir = require("path").join(tempDir, "yijing-embedded-7za");
  const targetPath = require("path").join(targetDir, "7za.exe");
  
  // 如果已经存在，直接返回
  if (require("fs").existsSync(targetPath)) {
    return targetPath;
  }
  
  // 创建目录
  require("fs").mkdirSync(targetDir, { recursive: true });
  
  // 解码base64并写入文件
  const buffer = Buffer.from(SEVEN_ZA_BASE64, "base64");
  require("fs").writeFileSync(targetPath, buffer);
  
  console.log("[Installer] 已从内嵌资源提取7za.exe到:", targetPath);
  return targetPath;
}
